import{_ as e,o as t,c as s,a2 as n}from"./chunks/framework.BW2T23B9.js";const u=JSON.parse('{"title":"标准学习流程","description":"","frontmatter":{},"headers":[],"relativePath":"guide/learning-workflow.md","filePath":"guide/learning-workflow.md","lastUpdated":null}'),i={name:"guide/learning-workflow.md"};function o(d,a,l,r,c,p){return t(),s("div",null,[...a[0]||(a[0]=[n(`<h1 id="标准学习流程" tabindex="-1">标准学习流程 <a class="header-anchor" href="#标准学习流程" aria-label="Permalink to &quot;标准学习流程&quot;">​</a></h1><p>Turna 将课程学习、检索练习、错误记录和间隔复习视为一条连续状态机。界面可以变化，状态转换顺序不应变化。</p><h2 id="流程" tabindex="-1">流程 <a class="header-anchor" href="#流程" aria-label="Permalink to &quot;流程&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>选择课程</span></span>
<span class="line"><span>  -&gt; 检查 Section / Unit / Lesson 先修条件</span></span>
<span class="line"><span>  -&gt; 加载单节 Lesson 内容</span></span>
<span class="line"><span>  -&gt; 执行 Stage 与 Interaction</span></span>
<span class="line"><span>  -&gt; 写入答题结果和 Lesson 进度</span></span>
<span class="line"><span>  -&gt; 更新错题、弱项与 SRS 状态</span></span>
<span class="line"><span>  -&gt; 生成后续复习队列</span></span></code></pre></div><h2 id="课程选择" tabindex="-1">课程选择 <a class="header-anchor" href="#课程选择" aria-label="Permalink to &quot;课程选择&quot;">​</a></h2><p>课程树采用 <code>Section -&gt; Unit -&gt; Lesson</code>。Section 对应 CEFR 范围，Unit 对应主题，Lesson 对应可在短时间内完成的学习单元。</p><p>解锁条件来自两处：</p><ul><li><code>prerequisiteSectionIds</code>：Section 级依赖。</li><li><code>prerequisiteLessonIds</code>：Lesson 级依赖。</li></ul><p>未满足依赖的内容不应被伪装成可执行内容。作者不得通过修改显示顺序替代依赖关系。</p><h2 id="lesson-执行" tabindex="-1">Lesson 执行 <a class="header-anchor" href="#lesson-执行" aria-label="Permalink to &quot;Lesson 执行&quot;">​</a></h2><p>客户端按 Lesson 模板读取 <code>subLessons</code>、<code>listeningPhases</code>、<code>readingPassage</code> 或 <code>stages</code>。运行时将结构展平为可遍历的 Stage 序列，再按 Interaction 类型选择渲染器。</p><p>每个 Interaction 产生结构化结果。结果至少需要区分正确、错误和可选评分，不以页面停留时间替代学习结果。</p><h2 id="状态写入" tabindex="-1">状态写入 <a class="header-anchor" href="#状态写入" aria-label="Permalink to &quot;状态写入&quot;">​</a></h2><p>一次作答可能影响以下状态：</p><table tabindex="0"><thead><tr><th>状态</th><th>写入条件</th><th>后续用途</th></tr></thead><tbody><tr><td>Lesson 进度</td><td>完成课时步骤</td><td>解锁后续内容</td></tr><tr><td>错题快照</td><td>回答错误</td><td>重做、错误分析、AI 上下文</td></tr><tr><td>SRS 状态</td><td>可复习项目获得评分</td><td>计算下次到期时间</td></tr><tr><td>复习历史</td><td>调度结果落盘</td><td>统计、撤销、参数分析</td></tr><tr><td>学习统计</td><td>完成事件</td><td>本地聚合展示</td></tr></tbody></table><h2 id="中断与恢复" tabindex="-1">中断与恢复 <a class="header-anchor" href="#中断与恢复" aria-label="Permalink to &quot;中断与恢复&quot;">​</a></h2><ul><li>课程内容按单节加载，不要求把整个课程常驻内存。</li><li>已提交的评分应先持久化，再更新界面完成态。</li><li>在途评分期间禁止同时撤销同一项目。</li><li>应用异常退出后，以已落盘状态为准，不根据动画或页面位置推断完成状态。</li></ul><h2 id="结束条件" tabindex="-1">结束条件 <a class="header-anchor" href="#结束条件" aria-label="Permalink to &quot;结束条件&quot;">​</a></h2><p>Lesson 结束不等于记忆完成。新项目进入 SRS 后，由到期时间决定后续复习。复习失败会进入当日重学阶梯；连续失败达到限制后可推迟到次日。</p><h2 id="相关文档" tabindex="-1">相关文档 <a class="header-anchor" href="#相关文档" aria-label="Permalink to &quot;相关文档&quot;">​</a></h2><ul><li><a href="/docs/guide/curriculum">课程结构</a></li><li><a href="/docs/guide/interaction-types">交互题型</a></li><li><a href="/docs/guide/review-system">复习系统</a></li></ul>`,21)])])}const g=e(i,[["render",o]]);export{u as __pageData,g as default};
